component.schema:
{
 "description": "GCPAuthEngineRole is the Schema for the gcpauthengineroles API",
 "properties": {
  "spec": {
   "description": "GCPAuthEngineRoleSpec defines the desired state of GCPAuthEngineRole",
   "properties": {
    "addGroupAliases": {
     "description": "If true, any auth token generated under this token will have associated group aliases, namely project-$PROJECT_ID,...",
     "type": "boolean"
    },
    "allowGCEInference": {
     "description": "A flag to determine if this role should allow GCE instances to authenticate by inferring service accounts from the GCE...",
     "type": "boolean"
    },
    "authentication": {
     "description": "Authentication is the kube auth configuraiton to be used to execute this request",
     "properties": {
      "namespace": {
       "description": "Namespace is the Vault namespace in which the operator authenticates, and in which the resource is managed unless...",
       "type": "string"
      },
      "path": {
       "default": "kubernetes",
       "description": "Path is the path of the role used for this kube auth authentication.",
       "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
       "type": "string"
      },
      "role": {
       "description": "Role the role to be used during authentication",
       "type": "string"
      },
      "serviceAccount": {
       "default": {
        "name": "default"
       },
       "description": "ServiceAccount is the service account used for the kube auth authentication",
       "properties": {
        "name": {
         "default": "",
         "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty.",
         "type": "string"
        }
       },
       "type": "object",
       "x-kubernetes-map-type": "atomic"
      },
      "targetNamespace": {
       "description": "TargetNamespace is the Vault namespace (not a Kubernetes namespace) in which the resource is managed, relative to the...",
       "pattern": "^(([^\\s/]*[^\\s/.][^\\s/]*|\\.{3,})(/([^\\s/]*[^\\s/.][^\\s/]*|\\.{3,}))*)?$",
       "type": "string"
      }
     },
     "type": "object"
    },
    "boundInstanceGroups": {
     "description": "The instance groups that an authorized instance must belong to in order to be authenticated.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundLabels": {
     "description": "A comma-separated list of GCP labels formatted as \"key:value\" strings that must be set on authorized GCE instances.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundProjects": {
     "default": [],
     "description": "An array of GCP project IDs. Only entities belonging to this project can authenticate under the role.",
     "items": {
      "type": "string"
     },
     "type": "array"
    },
    "boundRegions": {
     "description": "The list of regions that a GCE instance must belong to in order to be authenticated.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "boundServiceAccounts": {
     "default": [],
     "description": "An array of service account emails or IDs that login is restricted to, either directly or through an associated...",
     "items": {
      "type": "string"
     },
     "type": "array"
    },
    "boundZones": {
     "description": "The list of zones that a GCE instance must belong to in order to be authenticated.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "connection": {
     "description": "Connection represents the information needed to connect to Vault.",
     "properties": {
      "address": {
       "description": "Address Address of the Vault server expressed as a URL and port, for example: https://127.0.0.1:8200/",
       "type": "string"
      },
      "maxRetries": {
       "description": "MaxRetries Maximum number of retries when certain error codes are encountered.",
       "type": "integer"
      },
      "tLSConfig": {
       "properties": {
        "cacert": {
         "description": "Cacert Path to a PEM-encoded CA certificate file on the local disk.",
         "type": "string"
        },
        "skipVerify": {
         "description": "SkipVerify Do not verify Vault's presented certificate before communicating with it.",
         "type": "boolean"
        },
        "tlsSecret": {
         "description": "TLSSecret namespace-local secret containing the tls material for the connection.",
         "properties": {
          "name": {
           "default": "",
           "description": "Name of the referent.\nThis field is effectively required, but due to backwards compatibility is\nallowed to be empty.",
           "type": "string"
          }
         },
         "type": "object",
         "x-kubernetes-map-type": "atomic"
        },
        "tlsServerName": {
         "description": "TLSServerName Name to use as the SNI host when connecting via TLS.",
         "type": "string"
        }
       },
       "type": "object"
      },
      "timeOut": {
       "description": "Timeout Timeout variable. The default value is 60s.",
       "type": "string"
      }
     },
     "type": "object"
    },
    "maxJWTExp": {
     "description": "The number of seconds past the time of authentication that the login param JWT must expire within.",
     "type": "string"
    },
    "name": {
     "description": "Name of the role.",
     "type": "string"
    },
    "path": {
     "description": "Path at which to make the configuration.\nThe final path in Vault will be {[spec.authentication.namespace]}/{[spec.",
     "pattern": "^(?:/?[\\w;:@\u0026=\\$-\\.\\+]*)+/?",
     "type": "string"
    },
    "policies": {
     "description": "DEPRECATED: Please use the token_policies parameter instead. List of token policies to encode onto generated tokens.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "tokenBoundCIDRs": {
     "description": "List of CIDR blocks.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "tokenExplicitMaxTTL": {
     "description": "If set, will encode an explicit max TTL onto the token.",
     "type": "string"
    },
    "tokenMaxTTL": {
     "description": "The maximum lifetime for generated tokens. This current value of this will be referenced at renewal time.",
     "type": "string"
    },
    "tokenNoDefaultPolicy": {
     "description": "If set, the default policy will not be set on generated tokens; otherwise it will be added to the policies set in...",
     "type": "boolean"
    },
    "tokenNumUses": {
     "description": "The maximum number of times a generated token may be used (within its lifetime); 0 means unlimited.",
     "format": "int64",
     "minimum": 0,
     "type": "integer"
    },
    "tokenPeriod": {
     "description": "The maximum allowed period value when a periodic token is requested from this role.",
     "format": "int64",
     "minimum": 0,
     "type": "integer"
    },
    "tokenPolicies": {
     "description": "List of token policies to encode onto generated tokens.",
     "items": {
      "type": "string"
     },
     "type": "array",
     "x-kubernetes-list-type": "set"
    },
    "tokenTTL": {
     "description": "The incremental lifetime for generated tokens. This current value of this will be referenced at renewal time.",
     "type": "string"
    },
    "tokenType": {
     "description": "The type of token that should be generated.",
     "enum": [
      "service",
      "batch",
      "default",
      "default-service",
      "default-batch"
     ],
     "type": "string"
    },
    "type": {
     "description": "The type of this role. Certain fields correspond to specific roles and will be rejected otherwise.",
     "enum": [
      "iam",
      "gce"
     ],
     "type": "string"
    }
   },
   "required": [
    "name",
    "type"
   ],
   "type": "object"
  }
 },
 "title": "GCP Auth Engine Role",
 "type": "object"
}
